#!/usr/bin/env bash
set -Eeuo pipefail

EXPECTED_BRANCH="fix/module006-pipeline-modules-directory-superadmin-20260730-v2"
[[ "${GITHUB_REF_NAME:-}" == "$EXPECTED_BRANCH" ]] || {
  echo "ERROR: unexpected branch ${GITHUB_REF_NAME:-unknown}" >&2
  exit 1
}

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

cat > "$WORK/payload.b64" <<'PAYLOAD'
[... ELLIPSIZATION ...]
PAYLOAD
base64 -d "$WORK/payload.b64" > "$WORK/payload.tar.gz"
tar -xzf "$WORK/payload.tar.gz" -C "$WORK"

install -m 0644 "$WORK/IMPLEMENTATION-PLAN.md" docs/modules/module-006-toyota-hyundai-pipelines/IMPLEMENTATION-PLAN.md
install -m 0644 "$WORK/ProjectRegisterCenter.jsx" src/frontend/project-time-web/src/ProjectRegisterCenter.jsx
install -m 0644 "$WORK/project-register-center.css" src/frontend/project-time-web/src/project-register-center.css
install -m 0644 "$WORK/toyota-hyundai-pipeline-snapshot.js" src/frontend/project-time-web/src/toyota-hyundai-pipeline-snapshot.js
install -m 0644 "$WORK/inject-module-006-toyota-hyundai-pipeline.mjs" src/frontend/project-time-web/scripts/inject-module-006-toyota-hyundai-pipeline.mjs
install -m 0644 "$WORK/validate-module-006-toyota-hyundai-pipelines.mjs" src/frontend/project-time-web/scripts/validate-module-006-toyota-hyundai-pipelines.mjs

node --check src/frontend/project-time-web/src/toyota-hyundai-pipeline-snapshot.js
node --check src/frontend/project-time-web/scripts/inject-module-006-toyota-hyundai-pipeline.mjs
node --check src/frontend/project-time-web/scripts/validate-module-006-toyota-hyundai-pipelines.mjs

git diff --check

git add \
  docs/modules/module-006-toyota-hyundai-pipelines/IMPLEMENTATION-PLAN.md \
  src/frontend/project-time-web/src/ProjectRegisterCenter.jsx \
  src/frontend/project-time-web/src/project-register-center.css \
  src/frontend/project-time-web/src/toyota-hyundai-pipeline-snapshot.js \
  src/frontend/project-time-web/scripts/inject-module-006-toyota-hyundai-pipeline.mjs \
  src/frontend/project-time-web/scripts/validate-module-006-toyota-hyundai-pipelines.mjs

git diff --cached --check
if git diff --cached --quiet; then
  echo "ERROR: no source changes were staged." >&2
  exit 1
fi

git commit -m "Fix Module 006 pipeline data and module directory authority"

echo "MODULE006_SOURCE_COMMIT=$(git rev-parse HEAD)"
